import os
from typing import Any, Dict, List, Optional

from azure.ai.formrecognizer import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential


AZURE_FORM_RECOGNIZER_ENDPOINT = os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
AZURE_FORM_RECOGNIZER_KEY = os.environ["AZURE_FORM_RECOGNIZER_KEY"]
AZURE_FORM_RECOGNIZER_MODEL = "prebuilt-invoice"


def _field_content(field: Any) -> Any:
    if field is None:
        return None
    value = getattr(field, "value", None)
    if value is not None:
        return value
    return getattr(field, "content", None)


def _money_amount(field: Any) -> Optional[float]:
    value = _field_content(field)
    if value is None:
        return None
    amount = getattr(value, "amount", None)
    if amount is not None:
        return float(amount)
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(str(value).replace(",", ""))
    except Exception:
        return None


def _date_iso(field: Any) -> Optional[str]:
    value = _field_content(field)
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        return value.isoformat()
    return str(value)


def _string(field: Any) -> Optional[str]:
    value = _field_content(field)
    if value is None:
        return None
    return str(value).strip() or None


def _line_items(items_field: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    value = _field_content(items_field)
    if not value:
        return items

    for entry in value:
        item_value = getattr(entry, "value", None)
        if not isinstance(item_value, dict):
            continue

        description = _string(item_value.get("Description"))
        quantity = _field_content(item_value.get("Quantity"))
        unit = _string(item_value.get("Unit"))
        unit_price = _money_amount(item_value.get("UnitPrice"))
        amount = _money_amount(item_value.get("Amount"))
        product_code = _string(item_value.get("ProductCode"))
        date = _date_iso(item_value.get("Date"))
        tax = _money_amount(item_value.get("Tax"))
        tax_rate = _field_content(item_value.get("TaxRate"))

        if isinstance(quantity, str):
            try:
                quantity = float(quantity.replace(",", ""))
            except Exception:
                pass

        if isinstance(tax_rate, str):
            try:
                tax_rate = float(tax_rate.replace("%", "").replace(",", ""))
            except Exception:
                pass

        items.append(
            {
                "description": description,
                "quantity": quantity,
                "unit": unit,
                "unit_price": unit_price,
                "amount": amount,
                "product_code": product_code,
                "date": date,
                "tax": tax,
                "tax_rate": tax_rate,
            }
        )
    return items


def extract_invoice_fields(invoice_bytes: bytes) -> Dict[str, Any]:
    client = DocumentAnalysisClient(
        endpoint=AZURE_FORM_RECOGNIZER_ENDPOINT,
        credential=AzureKeyCredential(AZURE_FORM_RECOGNIZER_KEY),
    )

    poller = client.begin_analyze_document(
        AZURE_FORM_RECOGNIZER_MODEL,
        document=invoice_bytes,
    )
    result = poller.result()

    if not result.documents:
        return {
            "vendor": None,
            "date": None,
            "total": None,
            "line_items": [],
        }

    doc = result.documents[0]
    fields = doc.fields or {}

    vendor = (
        _string(fields.get("VendorName"))
        or _string(fields.get("RemittanceAddressRecipient"))
        or _string(fields.get("CustomerName"))
    )

    invoice_date = _date_iso(fields.get("InvoiceDate"))
    total = _money_amount(fields.get("InvoiceTotal"))
    items = _line_items(fields.get("Items"))

    return {
        "vendor": vendor,
        "date": invoice_date,
        "total": total,
        "line_items": items,
    }
